True def transform(grid):
    rows, cols = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and any(0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0
                                       for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1))):
                out[r][c] = 8
    return out
